-- Customer shopping behavior: SQL analysis (PostgreSQL)
-- Table: customer (3,900 customers)

-- quick look at the table
SELECT * FROM customer LIMIT 20;


-- Q1. What is the total revenue generated by male vs. female customers?
SELECT gender,
       SUM(purchase_amount) AS revenue
FROM customer
GROUP BY gender;
-- Male customers bring about twice the revenue of female customers
-- (157,890 vs 75,191). This is total revenue, so it may just be because
-- there are more male customers. See the check below.

-- Q1 check: customers and average spend per gender
SELECT gender,
       COUNT(*) AS customers,
       ROUND(AVG(purchase_amount), 2) AS avg_spend,
       SUM(purchase_amount) AS revenue
FROM customer
GROUP BY gender;
-- result: men are 2,652 customers and women are 1,248, but the average
-- spend is almost the same (59.54 vs 60.25). The revenue gap comes from the
-- number of customers, not from spending more per person.

-- Q2. Which customers used a discount but still spent more than the
-- average purchase amount?
SELECT customer_id,
       purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
  AND purchase_amount > (SELECT AVG(purchase_amount) FROM customer)
ORDER BY purchase_amount DESC;
-- 839 customers (about 21.5%) used a discount and still spent more than
-- the average (about 59.76). The highest purchase is 100.


-- Q3. Which are the top 5 products with the highest average review rating?
SELECT item_purchased,
       ROUND(AVG(review_rating)::numeric, 2) AS average_rating
FROM customer
GROUP BY item_purchased
ORDER BY average_rating DESC
LIMIT 5;
-- Gloves, Sandals, Boots, Hat and Skirt have the best ratings (3.86 to 3.78).
-- The difference between them is very small.


-- Q4. Compare the average purchase amounts between Standard and Express shipping.
SELECT shipping_type,
       ROUND(AVG(purchase_amount), 2) AS avg_purchase
FROM customer
WHERE shipping_type IN ('Express', 'Standard')
GROUP BY shipping_type;
-- Standard and Express are almost the same (58.46 vs 60.48).
-- Express is only about 2 higher.


-- Q5. Do subscribed customers spend more? Compare average spend and total
-- revenue between subscribers and non-subscribers.
SELECT subscription_status,
       COUNT(customer_id) AS total_customers,
       ROUND(AVG(purchase_amount), 2) AS avg_spend,
       SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC, avg_spend DESC;
-- Same average spend (59.49 vs 59.87). Non-subscribers bring more revenue
-- (170,436 vs 62,645) only because there are more of them (2,847 vs 1,053).


-- Q6. Which 5 products have the highest percentage of purchases with
-- discounts applied?
SELECT item_purchased,
       ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)
             / COUNT(*), 2) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;
-- Hat, Sneakers, Coat, Sweater and Pants have the highest discount rate
-- (50% down to 47.37%). Compare with the overall rate below.

-- Q6 check: overall discount rate
SELECT ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)
             / COUNT(*), 2) AS overall_discount_rate
FROM customer;

-- result: overall discount rate is 43%. The top 5 products are only
-- 4 to 7 points above it, so they depend on discounts a bit more than average,
-- but not by much.

-- Q7. Segment customers into New, Returning, and Loyal based on their number
-- of previous purchases, and show the count of each segment.
WITH customer_type AS (
    SELECT customer_id,
           previous_purchases,
           CASE
               WHEN previous_purchases = 1 THEN 'New'
               WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
               ELSE 'Loyal'
           END AS customer_segment
    FROM customer
)
SELECT customer_segment,
       COUNT(*) AS customers
FROM customer_type
GROUP BY customer_segment;
-- Most customers are Loyal (3,116), then Returning (701).
-- Only 83 are New.


-- Q8. What are the top 3 most purchased products within each category?
WITH item_counts AS (
    SELECT category,
           item_purchased,
           COUNT(customer_id) AS total_orders,
           ROW_NUMBER() OVER (PARTITION BY category
                              ORDER BY COUNT(customer_id) DESC) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT *
FROM item_counts
WHERE item_rank <= 3;
-- Accessories: Jewelry, Sunglasses, Belt. Clothing: Blouse, Pants, Shirt.
-- Footwear: Sandals, Shoes, Sneakers. Outerwear: Jacket, Coat (only 2 products).
-- Order counts are very close and some are tied.


-- Q9. Are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT CASE WHEN previous_purchases > 5 THEN 'Repeat buyer'
            ELSE 'Not repeat' END AS buyer_type,
       COUNT(customer_id) AS customers,
       ROUND(100.0 * SUM(CASE WHEN subscription_status = 'Yes' THEN 1 ELSE 0 END)
             / COUNT(*), 2) AS subscription_rate
FROM customer
GROUP BY buyer_type;
-- Repeat buyers subscribe a bit more (27.56% vs 22.41%), but most of them
-- (about 72%) are still not subscribed.


-- Q10. What is the revenue contribution of each age group?
SELECT age_group,
       SUM(purchase_amount) AS total_revenue,
       ROUND(100.0 * SUM(purchase_amount) / SUM(SUM(purchase_amount)) OVER (), 2)
           AS revenue_pct
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;
-- Revenue is almost equal across age groups. Young Adults are first (26.7%)
-- and Seniors are last (23.9%).